#include "../Source/PluginProcessor.h"
#include <iostream>
#include <stdexcept>
namespace {
void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* parameter=p.state.getParameter(id);check(parameter!=nullptr,"parameter exists");parameter->setValueNotifyingHost(parameter->convertTo0to1(value));}
void dry(SpaceInfinityProcessor& p){for(const char* id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","convolverEnabled","eqEnabled","pumpEnabled","gateEnabled"})set(p,id,0);}
double energy(SpaceInfinityProcessor& p,float velocity,int note=48){p.prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);double sum=0;for(int block=0;block<188;++block){juce::MidiBuffer midi;if(block==0)midi.addEvent(juce::MidiMessage::noteOn(1,note,velocity),0);p.processBlock(audio,midi);if(block>60)for(int i=0;i<256;++i){const float v=audio.getSample(0,i);check(std::isfinite(v)&&std::abs(v)<1,"bounded audio");sum+=v*v;}}return sum;}
}
int runGrooveSmoke(){try{
    const auto at=[](float swing,int samples){studio::Rhythm fx;fx.prepare(48000);studio::Rhythm::Settings s;s.gate=true;s.rate=2;s.swing=swing;s.attack=.1f;s.release=.1f;for(int i=0;i<16;++i)s.steps[size_t(i)]=i%2?0:1;fx.configure(s,120);float out=0;for(int i=0;i<samples;++i)out=fx.process(1,1,0)[0];return out;};
    check(at(0,6600)<.1f&&at(.2f,6600)>.9f&&at(.2f,7800)<.1f,"swing delays the offbeat boundary");
    const auto acid=[](float velocity){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(10);dry(*p);set(*p,"ampVelocity",0);set(*p,"filterEnvAmount",0);set(*p,"ampSustain",1);set(*p,"res",.1f);set(*p,"drive",0);return energy(*p,velocity);};
    const double soft=acid(.3f),hard=acid(1);check(soft>0&&hard>soft*1.3,"velocity opens acid cutoff independently of volume");std::cout<<"Acid accent energy ratio: "<<hard/soft<<std::endl;
    const auto organ=[](float velocity,bool sensitive){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(12);dry(*p);set(*p,"filterVelocity",0);set(*p,"ampVelocity",sensitive?1:0);return energy(*p,velocity);};
    const double flatSoft=organ(.3f,false),flatHard=organ(1,false);check(std::abs(flatSoft-flatHard)<flatHard*.00001,"organ volume can ignore velocity");check(organ(1,true)>organ(.3f,true)*4,"velocity volume control still works");
    const auto sub=[](float cutoff,float level){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(0);dry(*p);set(*p,"osc1Enabled",0);set(*p,"osc2Enabled",0);set(*p,"subLevel",level);set(*p,"cutoff",cutoff);return energy(*p,.8f);};
    const double low=sub(80,.4f),high=sub(16000,.4f);check(low>1&&std::abs(low-high)<high*.00001&&sub(80,0)<.00001,"sine sub bypasses the voice filter");
    const auto table=[](bool moving){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(9);dry(*p);set(*p,"ampLong",0);set(*p,"attack",0);set(*p,"osc2Enabled",0);set(*p,"mix",0);set(*p,"noiseLevel",0);set(*p,"cutoff",16000);set(*p,"macro0",0);set(*p,p->lfoParameterId(0,"Enabled"),moving?1:0);set(*p,p->lfoParameterId(1,"Enabled"),0);set(*p,p->lfoParameterId(2,"Enabled"),0);set(*p,p->lfoParameterId(0,"Sync"),0);set(*p,p->lfoParameterId(0,"Speed"),1);
        p->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);std::vector<float> result;for(int b=0;b<188;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p->processBlock(audio,midi);for(int i=0;i<256;++i)result.push_back(audio.getSample(0,i));}return result;};
    const auto still=table(false),moving=table(true);double difference=0;for(size_t i=0;i<still.size();++i)difference+=std::abs(still[i]-moving[i]);check(difference>1,"wavetable scan modulation changes actual audio");
    auto pad=std::make_unique<SpaceInfinityProcessor>();pad->loadPreset(9);check(pad->tableFrameCount()==3,"factory wavetable frames");pad->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);double first=0,last=0;
    const auto folder=juce::File::getCurrentWorkingDirectory().getChildFile("audition");folder.createDirectory();const auto file=folder.getChildFile("Nebula Pulse Pad Preview.wav");file.deleteFile();auto stream=file.createOutputStream();juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.get(),48000,2,24,{},0));check(writer!=nullptr,"pad preview");stream.release();
    for(int b=0;b<4500;++b){juce::MidiBuffer midi;if(b==0)for(int note:{48,55,60})midi.addEvent(juce::MidiMessage::noteOn(1,note,.8f),0);pad->processBlock(audio,midi);if(b<2250)check(writer->writeFromAudioSampleBuffer(audio,0,256),"pad preview write");for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const float v=audio.getSample(ch,i);check(std::isfinite(v)&&std::abs(v)<1,"pad bounded");if(b>=375&&b<1125)first+=v*v;if(b>=3375&&b<4125)last+=v*v;}}
    check(first>1&&last>first*.65,"gated pad keeps its sustained level");std::cout<<"Nebula sustained energy ratio: "<<last/first<<std::endl;
    auto house=std::make_unique<SpaceInfinityProcessor>();house->loadPreset(11);house->prepareToPlay(48000,256);int notes=0;float minVelocity=1,maxVelocity=0;double chordEnergy=0;
    for(int b=0;b<750;++b){juce::MidiBuffer midi;if(b==0)for(int note:{48,52,55})midi.addEvent(juce::MidiMessage::noteOn(1,note,.8f),0);house->processBlock(audio,midi);for(const auto event:house->generatedNotes())if(event.getMessage().isNoteOn()){++notes;minVelocity=std::min(minVelocity,event.getMessage().getFloatVelocity());maxVelocity=std::max(maxVelocity,event.getMessage().getFloatVelocity());}for(int i=0;i<256;++i)chordEnergy+=audio.getSample(0,i)*audio.getSample(0,i);}
    check(notes>20&&maxVelocity-minVelocity>.25f&&chordEnergy>1,"house arp produces audible accented notes");
    juce::MemoryBlock state;pad->getStateInformation(state);house->setStateInformation(state.getData(),int(state.getSize()));check(house->tableFrameCount()==3&&house->selectedPresetKey()=="F129"&&house->state.getRawParameterValue("gateSwing")->load()==pad->state.getRawParameterValue("gateSwing")->load(),"new table and gate recall");
    auto womp=std::make_unique<SpaceInfinityProcessor>();womp->loadPreset(14);womp->prepareToPlay(48000,256);
    const auto wompFile=folder.getChildFile("Iron Surge Bass Preview.wav");wompFile.deleteFile();auto wompStream=wompFile.createOutputStream();std::unique_ptr<juce::AudioFormatWriter> wompWriter(wav.createWriterFor(wompStream.get(),48000,2,24,{},0));check(wompWriter!=nullptr,"womp preview");wompStream.release();
    std::array<double,24> wompLevels{};float wompPeak=0;
    for(int phrase=0;phrase<24;++phrase)for(int b=0;b<188;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,36,.85f),0);if(b==75)midi.addEvent(juce::MidiMessage::noteOff(1,36),0);womp->processBlock(audio,midi);if(phrase<8)check(wompWriter->writeFromAudioSampleBuffer(audio,0,256),"womp preview write");for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const float v=audio.getSample(ch,i);check(std::isfinite(v)&&std::abs(v)<1,"womp finite output");wompPeak=std::max(wompPeak,std::abs(v));if(b<75)wompLevels[size_t(phrase)]+=v*v;}}
    double wompFirst=0,wompLast=0;for(int i=2;i<8;++i)wompFirst+=wompLevels[size_t(i)];for(int i=18;i<24;++i)wompLast+=wompLevels[size_t(i)];check(wompFirst>1&&wompLast>wompFirst*.70&&wompPeak<.85f,"womp repeated notes hold level with headroom");
    const auto driveCapture=[](float drive){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(14);dry(*p);set(*p,"filterInputDrive",drive);p->prepareToPlay(48000,256);juce::AudioBuffer<float> b(2,256);std::vector<float> result;for(int n=0;n<100;++n){juce::MidiBuffer midi;if(n==0)midi.addEvent(juce::MidiMessage::noteOn(1,36,.85f),0);p->processBlock(b,midi);for(int i=0;i<256;++i)result.push_back(b.getSample(0,i));}return result;};
    const auto clean=driveCapture(0),driven=driveCapture(.35f);double driveDifference=0;for(size_t i=0;i<clean.size();++i)driveDifference+=std::abs(clean[i]-driven[i]);check(driveDifference>1,"pre-filter drive changes audible waveform");
    womp->getStateInformation(state);house->setStateInformation(state.getData(),int(state.getSize()));check(house->selectedPresetKey()=="F134"&&house->state.getRawParameterValue("filterInputDrive")->load()==.35f,"womp and pre-drive recall");
    std::cout<<"Iron Surge energy ratio: "<<wompLast/wompFirst<<", peak "<<wompPeak<<std::endl;
    const auto growlCapture=[](float depth){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(26);dry(*p);set(*p,p->modulationRouteId(4,2,true),depth);p->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);std::vector<float> result;
        for(int b=0;b<188;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,36,.85f),0);p->processBlock(audio,midi);for(int i=0;i<256;++i){const float v=audio.getSample(0,i);check(std::isfinite(v)&&std::abs(v)<.95f,"growl bounded output");result.push_back(v);}}return result;};
    const auto fixedFm=growlCapture(0),movingFm=growlCapture(.20f);double fmDifference=0;for(size_t i=0;i<fixedFm.size();++i)fmDifference+=std::abs(fixedFm[i]-movingFm[i]);check(fmDifference>1,"warp destination modulates FM in real audio");
    for(int preset:{21,22,25}){auto arp=std::make_unique<SpaceInfinityProcessor>();arp->loadPreset(preset);arp->prepareToPlay(48000,256);int generated=0;double e=0;for(int b=0;b<375;++b){juce::MidiBuffer midi;if(b==0)for(int note:{48,52,55})midi.addEvent(juce::MidiMessage::noteOn(1,note,.8f),0);arp->processBlock(audio,midi);for(const auto event:arp->generatedNotes())if(event.getMessage().isNoteOn())++generated;for(int i=0;i<256;++i)e+=audio.getSample(0,i)*audio.getSample(0,i);}check(generated>=7&&e>1,"new arp emits notes and audio from a held chord");}
    const auto subFmCapture=[](int mode){auto p=std::make_unique<SpaceInfinityProcessor>();p->loadPreset(28);dry(*p);set(*p,"chorusEnabled",0);set(*p,"osc1Octave",0);set(*p,"osc2Enabled",0);set(*p,"mix",0);set(*p,"subLevel",0);set(*p,"filterEnvAmount",0);set(*p,"cutoff",16000);set(*p,"attack",0);set(*p,"ampSustain",1);set(*p,"osc1WarpEnvelope",0);set(*p,"osc1Warp",mode);p->prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);std::vector<float> result;for(int b=0;b<100;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,69,.8f),0);p->processBlock(audio,midi);for(int i=0;i<256;++i)result.push_back(audio.getSample(0,i));}return result;};
    const auto noSubFm=subFmCapture(0),subFm=subFmCapture(4);double subFmDifference=0;for(size_t i=0;i<subFm.size();++i)subFmDifference+=std::abs(subFm[i]-noSubFm[i]);check(subFmDifference>1,"FM from sub works while the sub is inaudible");
    auto retrigger=std::make_unique<SpaceInfinityProcessor>();retrigger->loadPreset(32);dry(*retrigger);for(const char* id:{"phaserEnabled","flangerEnabled","subLevel","noiseLevel","filterEnvAmount","filterInputDrive","drive","attack","release","res","osc2Enabled","mix"})set(*retrigger,id,0);set(*retrigger,"wave",2);set(*retrigger,"osc1Octave",0);set(*retrigger,"osc1Unison",1);set(*retrigger,"ampSustain",1);set(*retrigger,"cutoff",16000);retrigger->prepareToPlay(48000,256);
    const auto silence=[&]{for(int b=0;b<188;++b){juce::MidiBuffer midi;retrigger->processBlock(audio,midi);}};silence();
    const auto attack=[&]{std::vector<float> result;for(int b=0;b<30;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,69,.8f),0);retrigger->processBlock(audio,midi);for(int i=0;i<256;++i)result.push_back(audio.getSample(0,i));}juce::MidiBuffer off;off.addEvent(juce::MidiMessage::noteOff(1,69),0);retrigger->processBlock(audio,off);silence();return result;};
    const auto attackA=attack(),attackB=attack();double phaseDifference=0;for(size_t i=0;i<attackA.size();++i)phaseDifference+=std::abs(attackA[i]-attackB[i]);check(phaseDifference<.001,"phase retrigger gives repeatable attacks");
    auto offbeat=std::make_unique<SpaceInfinityProcessor>();offbeat->loadPreset(31);offbeat->prepareToPlay(48000,256);double stereoEnergy=0,monoEnergy=0;for(int b=0;b<375;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);offbeat->processBlock(audio,midi);for(int i=0;i<256;++i){const float l=audio.getSample(0,i),r=audio.getSample(1,i);check(std::isfinite(l)&&std::isfinite(r),"offbeat finite output");stereoEnergy+=.5*(l*l+r*r);monoEnergy+=.25*(l+r)*(l+r);}}check(stereoEnergy>.01&&monoEnergy>stereoEnergy*.70,"offbeat retains energy in mono");
    auto reese=std::make_unique<SpaceInfinityProcessor>();reese->loadPreset(27);check(energy(*reese,.85f,48)>1,"Reese bass produces sustained audio");
    std::cout<<"Groove bank: swing, accents, sub, wavetable movement, sustained pad and arp passed"<<std::endl;return 0;
}catch(const std::exception& e){std::cerr<<"Groove bank: "<<e.what()<<std::endl;return 150;}}
